// Écrit une clé plateforme_config via le backend (protégé par requirePermission("configuration","update"))
// au lieu d'un upsert Supabase direct depuis le frontend, qui contournait tout contrôle de permission.
const savePlateformeConfig = (key, valeur) =>
  fetch(`${API_URL}/api/admin/plateforme-config/${key}`, { method:"PUT", headers:authHeaders(), body:JSON.stringify({ valeur }) })
    .then(r => { if (!r.ok) throw new Error("Échec de la sauvegarde"); return r.json(); });

