// Utilisé par l'onglet "Gestion des droits" (repris tel quel d'AdminDashboard, cf. tableau
// utilisateurs) pour afficher le(s) centre(s) assigné(s) à un compte plutôt que ses ids bruts.
const scopeLabel = (scope) => {
  if (!scope || scope.length === 0 || scope.includes("national")) return null;
  return scope.map(s => CENTRES_BET.find(c => c.id === s)?.label.replace("BET ","") || s).join(", ");
};

