  const caEvolutionSA = useMemo(() => {
    const mois = derniersMoisSA(12);
    const parMois = {};
    mois.forEach(m => { parMois[m.key] = 0; });
    paiements.forEach(p => {
      const key = (p.date_paiement || "").slice(0,7);
      if (key in parMois) parMois[key] += Number(p.montant_recu || 0);
    });
    return {
      labels: mois.map(m => m.label),
      datasets: [{
        label: "CA encaissé",
        data: mois.map(m => parMois[m.key]),
        borderColor: BET_COLOR, backgroundColor: BET_COLOR + "22",
        fill: true, tension: 0.35, pointRadius: 3, pointBackgroundColor: BET_COLOR,
      }],
    };
  }, [paiements]);

